mapper.update:
UPDATE finance_shareholder fs SET deleted = true, updated_at = now() FROM ( VALUES
(#{p.companyId}::bigint, #{p.childId}::bigint)
) AS scope(company_id, finance_id) WHERE fs.company_id = scope.company_id AND fs.finance_id = scope.finance_id AND fs.deleted = false AND fs.sync_id != #{syncId}::uuid
